def same(a,b):
    if type(a) is not type(b): return False
    if isinstance(a,dict): return a.keys()==b.keys() and all(same(a[k],b[k]) for k in b)
    if isinstance(a,list): return len(a)==len(b) and all(same(x,y) for x,y in zip(a,b))
    return a==b
def diff(a,b,path=''):
    if type(a) is not type(b): print('TYPE',path,type(a),type(b)); return
    if isinstance(a,dict):
        for k in a:
            if k not in b: print('MISSING',path,k); 
            else: diff(a[k],b[k],path+'/'+k)
        for k in b:
            if k not in a: print('EXTRA',path,k)
    elif isinstance(a,list):
        if len(a)!=len(b): print('LEN',path,len(a),len(b)); return
        for i,(x,y) in enumerate(zip(a,b)): diff(x,y,path+'[%d]'%i)
diff(got[1],exp[1])
